import java.util.*;
import java.lang.*;
import java.io.*;

class Codechef
{
	public static void main (String[] args) throws java.lang.Exception
	{
		// your code goes here
		Scanner sc = new Scanner(System.in);
		int t = sc.nextInt();
		while(t-- > 0){
		    int n = sc.nextInt();
		    int m = 3*n;
		    
		    long [] a = new long[m];
		    for(int i = 0;i<m;i++){
		        a[i] = sc.nextLong();
		    }
		    Arrays.sort(a);
		    for(int i= 0;i<m/2;i++){
		        long temp = a[i];
		        a[i] = a[m-1-i];
		        a[m-1-i] = temp;
		    }
		    
		    long [] pref = new long[m+1];
		    for(int i = 0;i<m;i++){
		        pref[i+1]= pref[i]+a[i];
		    }
		    long ans = Long.MIN_VALUE;
		    for(int A = 0;A<=n;A++){
		        int low = 0;
		        int high = n-A;
		        while(low < high){
		            int B = (low+high)/2;
		            int i = A+2*B;
		            int j = 3*n-2*A-B;
		            
		            long diff = a[i+1]+a[i]-3*a[j-1];
		            if(diff >= 0){
		                low = B+1;
		            }else{
		                 high= B;
		            }
		        }
		        
		    
		    for(int B = Math.max(0 , low-1);B<=Math.min(n-A,low);B++){
		        int c = n-A-B;
		        int p1 = A;
		        int p2 = A+2*B;
		        int p3 = 3*n-2*A-B;
		        
		        long value = 6*pref[p1]+4*(pref[p2]-pref[p1])+3*(pref[p3]-pref[p2]);
		       ans =  Math.max(ans , value);
		        }
		}
		System.out.println(ans);
		}
	}
	
}
